window.SAP_CH_DATA = {"id":"ch_64","title":"Picking","start_page":560,"end_page":566,"slides":[{"page":560,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n19\n❑App thực hiện: PDA - Picking\nBước 1: \nChọn app Picking trên PDA\nBước 2:\nNgười dùng chọn lệnh xuất \nhàng tổng tương ứng ở màn \nhình Picking\nĐối với thiết bị PDA chuyên \ndụng, người dùng có thể nhấn \nvào nút Scan của máy để quét \nID Pallet/ ID hàng\nĐối với thiết bị điện thoại, \nngười dùng có thể nhấn vào \nnút Camera để quét ID Pallet/ \nID hàng\nĐối với trường hợp này, chỉ \ngợi ý nguyên Pallet\n✓Thực hiện Picking trên PDA\nWM.05D.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nTHÀNH PHẨM QUA LẠI GIỮA CÁC KHO TRONG NHÀ MÁY (WM – WM: CÓ \nBARCODE)","images":["","",""]},{"page":561,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n20\n❑App thực hiện: PDA - Picking\nSau khi người dùng quét ID \nPallet, trên PDA check và ghi \nnhận đủ số lượng so với số \nlượng gợi ý, PDA sẽ hiển thị \nmàu xanh\n✓Thực hiện Picking trên PDA\nWM.05D.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nTHÀNH PHẨM QUA LẠI GIỮA CÁC KHO TRONG NHÀ MÁY (WM – WM: CÓ \nBARCODE)","images":["",""]},{"page":562,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n21\n❑App thực hiện: Picking\nBước 3:\nNhập app: “Picking” vào \nthanh tìm kiếm\nBước 4: \nClick chọn vào app Picking\n✓Picking trên SAP\nWM.05D.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nTHÀNH PHẨM QUA LẠI GIỮA CÁC KHO TRONG NHÀ MÁY (WM – WM: CÓ \nBARCODE)","images":[""]},{"page":563,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n22\n❑App thực hiện: Picking\nBước 5: \nĐiền lệnh xuất hàng tổng ở \ntham số để lọc dữ liệu\nBước 6:\nNhấn Go để lọc dữ liệu cần \ntìm \n✓Picking trên SAP\nWM.05D.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nTHÀNH PHẨM QUA LẠI GIỮA CÁC KHO TRONG NHÀ MÁY (WM – WM: CÓ \nBARCODE)","images":[""]},{"page":564,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n23\n❑App thực hiện: Picking\nBước 7: \nThực hiện chọn tất cả các \ndòng của lệnh xuất hàng tổng \nvừa thực hiện Pick hàng\nBước 8:\nNhấn Check để kiểm tra dữ \nliệu\nBước 9:\nSau khi nhấn Check và dữ liệu \nkhông còn sai sót, tiếp tục \nnhấn Post để tạo giao dịch \ntrên hệ thống\n \n✓Picking trên SAP\nWM.05D.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nTHÀNH PHẨM QUA LẠI GIỮA CÁC KHO TRONG NHÀ MÁY (WM – WM: CÓ \nBARCODE)","images":[""]},{"page":565,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n24\n❑App thực hiện: Picking\nSau khi người dùng nhấn \nCheck và Post thành công, lúc \nnày tồn kho trên hệ thống đã \nchuyển về vị trí vùng đệm \nxuất, sẵn sàng cho việc phân \nhàng\n✓Xuất kho bán hàng – Kho WM\nWM.05D.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nTHÀNH PHẨM QUA LẠI GIỮA CÁC KHO TRONG NHÀ MÁY (WM – WM: CÓ \nBARCODE)","images":[""]},{"page":566,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n25\n❑App thực hiện: Picking\nSau khi hoàn thành giao dịch, \ntồn kho được chuyển sang \nvùng đệm xuất\n✓Xuất kho bán hàng – Kho WM\nWM.05D.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nTHÀNH PHẨM QUA LẠI GIỮA CÁC KHO TRONG NHÀ MÁY (WM – WM: CÓ \nBARCODE)","images":[""]}]};